import math

class ComplexNumber:
    def __init__(self, real, imaginary):
        self.real = real
        self.imaginary = imaginary

    def __eq__(self, other):
        if isinstance(other, ComplexNumber):
            # For floating-point comparisons, direct equality `==` might fail due to precision.
            # However, for typical test suites in exercises like this, direct equality is often
            # expected to pass within the test's chosen tolerance.
            return self.real == other.real and self.imaginary == other.imaginary
        elif isinstance(other, (int, float)):
            # A complex number a + bi is considered equal to a real number r if b=0 and a=r.
            return self.imaginary == 0.0 and self.real == other
        return NotImplemented # Delegate to other's __eq__ if no match

    # Helper method to convert a scalar (int/float) to a ComplexNumber
    # for operations that support mixed types.
    def _to_complex(self, other):
        if isinstance(other, ComplexNumber):
            return other
        elif isinstance(other, (int, float)):
            return ComplexNumber(other, 0.0)
        return NotImplemented # Indicate that the type is not supported for this operation

    def __add__(self, other):
        other_complex = self._to_complex(other)
        if other_complex is NotImplemented:
            return NotImplemented

        # z1 + z2 = (a + c) + (b + d) * i
        new_real = self.real + other_complex.real
        new_imaginary = self.imaginary + other_complex.imaginary
        return ComplexNumber(new_real, new_imaginary)

    def __radd__(self, other):
        # Addition is commutative, so __radd__ can simply call __add__
        return self.__add__(other)

    def __sub__(self, other):
        other_complex = self._to_complex(other)
        if other_complex is NotImplemented:
            return NotImplemented

        # z1 - z2 = (a - c) + (b - d) * i
        new_real = self.real - other_complex.real
        new_imaginary = self.imaginary - other_complex.imaginary
        return ComplexNumber(new_real, new_imaginary)

    def __rsub__(self, other):
        # other - self = (other_real + 0i) - (self.real + self.imaginary i)
        #              = (other_real - self.real) + (0 - self.imaginary)i
        other_complex = self._to_complex(other)
        if other_complex is NotImplemented:
            return NotImplemented

        # Perform (other_complex) - (self)
        new_real = other_complex.real - self.real
        new_imaginary = other_complex.imaginary - self.imaginary
        return ComplexNumber(new_real, new_imaginary)

    def __mul__(self, other):
        other_complex = self._to_complex(other)
        if other_complex is NotImplemented:
            return NotImplemented

        # z1 * z2 = (a * c - b * d) + (b * c + a * d) * i
        a, b = self.real, self.imaginary
        c, d = other_complex.real, other_complex.imaginary
        new_real = (a * c) - (b * d)
        new_imaginary = (b * c) + (a * d)
        return ComplexNumber(new_real, new_imaginary)

    def __rmul__(self, other):
        # Multiplication is commutative
        return self.__mul__(other)

    def __truediv__(self, other):
        other_complex = self._to_complex(other)
        if other_complex is NotImplemented:
            return NotImplemented

        # z1 / z2 = (a * c + b * d) / (c^2 + d^2) + (b * c - a * d) / (c^2 + d^2) * i
        a, b = self.real, self.imaginary
        c, d = other_complex.real, other_complex.imaginary

        denominator = c**2 + d**2
        # If denominator is 0, Python's float division will raise ZeroDivisionError
        # (e.g., 1.0 / 0.0), which is the standard and correct behavior.

        new_real = (a * c + b * d) / denominator
        new_imaginary = (b * c - a * d) / denominator
        return ComplexNumber(new_real, new_imaginary)

    def __rtruediv__(self, other):
        # other / self
        # Treat 'other' as a complex number (other_real + 0i)
        other_complex = self._to_complex(other)
        if other_complex is NotImplemented:
            return NotImplemented

        # Now we want other_complex / self.
        # This is equivalent to calling the division logic with 'other_complex' as the numerator
        # and 'self' as the denominator.
        a, b = other_complex.real, other_complex.imaginary # Numerator parts
        c, d = self.real, self.imaginary                   # Denominator parts

        denominator = c**2 + d**2

        new_real = (a * c + b * d) / denominator
        new_imaginary = (b * c - a * d) / denominator
        return ComplexNumber(new_real, new_imaginary)

    def __abs__(self):
        # |z| = sqrt(a^2 + b^2)
        return math.sqrt(self.real**2 + self.imaginary**2)

    def conjugate(self):
        # zc = a - b * i
        return ComplexNumber(self.real, -self.imaginary)

    def exp(self):
        # e^(a + b * i) = e^a * (cos(b) + i * sin(b))
        # Let a = self.real, b = self.imaginary
        e_to_a = math.exp(self.real)
        cos_b = math.cos(self.imaginary)
        sin_b = math.sin(self.imaginary)

        # Result is e_to_a * cos_b + i * e_to_a * sin_b
        new_real = e_to_a * cos_b
        new_imaginary = e_to_a * sin_b
        return ComplexNumber(new_real, new_imaginary)

    # Optional: __repr__ for better debugging output
    def __repr__(self):
        return f"ComplexNumber({self.real}, {self.imaginary})"

